document.querySelectorAll("form.lisn-notify-form").forEach(e=>{const n=e.dataset.endpoint,s=e.querySelector("input[type=email]"),o=e.querySelector("input[name=website]"),t=e.querySelector(".lisn-notify-status");e.addEventListener("submit",i=>{if(i.preventDefault(),!n)return;if(!s.checkValidity()){t.textContent="Please enter a valid email address.";return}const a={type:"subscribe",list:e.dataset.list,tag:e.dataset.tag||"",source:location.pathname,hp:o?o.value:"",email:s.value.trim(),consent:e.dataset.consent};fetch(n,{method:"POST",mode:"no-cors",headers:{"Content-Type":"text/plain;charset=utf-8"},body:JSON.stringify(a)}).then(()=>{t.textContent="Thank you. We will email you when a new study opens.",e.reset()}).catch(()=>{t.textContent="Sorry, that did not go through. Please try again later."})})})